/* ============================================================================
   Multilingual content dictionary — French (fr) & Japanese (ja).
   Keyed by the EXACT English source text (innerHTML for [data-pt], textContent
   for [data-i18n]/headings, JSON "en" values for modals), whitespace-collapsed,
   so the runtime engine in script.js (trLookup) can fall back through it for any
   language other than EN/PT. Portuguese stays in the inline data-pt attrs / I18N.
   Untranslatable terms keep the English term in parentheses. HTML tags in a key
   are preserved in the value (engine assigns innerHTML for those).
   ========================================================================== */
window.TR = window.TR || { fr: {}, ja: {} };

